import sqlite3

import streamlit as st

import config
import database
import rankings
import ui_components


def _category_choices(connection):
    """Build ordered direction/bundle choices without putting UI labels into SQL."""
    choices = {'All categories': (None, None)}
    for row in database.get_categories_df(connection).to_dict('records'):
        choices[row['direction_name']] = (row['direction_key'], None)
        choices['    ↳ ' + row['bundle_name']] = (row['direction_key'], row['bundle_key'])
    return choices


def _ranking_pair(connection, metric, user_id, direction, bundle):
    """Show You and All users side by side with optional aggregate-only data tables."""
    for column, scope, label in zip(st.columns(2), ('you', 'all'), ('You', 'All users')):
        with column:
            st.subheader(label)
            frame = rankings.get_ranking(connection, metric, scope, user_id, direction, bundle)
            if frame.empty:
                st.info(config.RANKING_EMPTY_MESSAGE)
            else:
                st.pyplot(rankings.plot_ranking(frame, rankings.METRICS[metric] + ' · ' + label),
                           alt=rankings.METRICS[metric] + ' for ' + label)
            if metric == 'best_rated':
                minimum = config.MIN_RATINGS_YOU if scope == 'you' else config.MIN_RATINGS_ALL_USERS
                st.caption(f'At least {minimum} rating(s) per activity series.')
            with st.expander('Show table'):
                st.dataframe(frame, hide_index=True, width='stretch')


def render_rankings(connection):
    """Render all four ranking tabs and an unfiltered direction summary."""
    st.title('Rankings')
    st.write('Anonymised statistics. All users = 60 synthetic demo users + you.')
    st.caption('Activities are grouped by series across dates. Cancelled plans are excluded. '
               'The charts use direction colours; the tables also name each direction.')
    choices = _category_choices(connection)
    selection = st.selectbox('Category', list(choices), key='ww_ranking_category')
    direction, bundle = choices[selection]
    user_id = database.get_current_user_id(connection)
    # Course: L04 – tracked tabs render the selected metric only, avoiding eight charts per rerun.
    tabs = st.tabs(list(rankings.METRICS.values()), key='ww_ranking_tab', on_change='rerun')
    for tab, metric in zip(tabs, rankings.METRICS):
        with tab:
            if tab.open:
                _ranking_pair(connection, metric, user_id, direction, bundle)
    overview = rankings.category_overview(connection, user_id)
    st.subheader('Category overview')
    st.caption('All categories. Bars count current confirmed plans; the table also shows average '
               'ratings from attended activities. Empty averages mean no ratings yet.')
    st.pyplot(rankings.plot_category_overview(overview), alt='Confirmed plans per direction')
    with st.expander('Show category overview table'):
        st.dataframe(overview, hide_index=True, width='stretch')
    ui_components.render_sidebar_status()


try:
    render_rankings(ui_components.cached_connection())
except (OSError, ValueError, KeyError, sqlite3.Error):
    st.error('Could not load rankings. Please refresh the page and try again.')
